// Builds dist/data/enemy-weapons.js: each enemy's attacks from its wiki "Weapons Loadout" boxes
// (db/source/wiki_enemy_weapons.json, scripts/fetch-enemy-weapons.mjs) with the site's Korean
// names (db/source/enemy_weapon_korean.json), and the Helldiver health and armor factors from
// Template:Armor Ratings. Do not edit the output.
// Usage: node scripts/build-enemy-weapons.mjs
import { readFile, writeFile } from 'node:fs/promises';
import { enemies } from '../dist/data/combat-data.js';
import { pageTitle } from './enemy-page-title.mjs';
import { enemyAttack, armorRatings, ARMOR_RATINGS } from './enemy-weapon-parse.mjs';

const read = async name => JSON.parse(await readFile(new URL(`../db/source/${name}`, import.meta.url), 'utf8'));

export async function buildEnemyWeapons() {
  const source = await read('wiki_enemy_weapons.json');
  const korean = (await read('enemy_weapon_korean.json')).names;
  const ratings = armorRatings(source.armorRatings.text);
  for (const rating of ARMOR_RATINGS) if (!ratings.factors[rating]) throw new Error(`Template:Armor Ratings has no factor for armor ${rating}`);
  if (!ratings.health || !ratings.chest) throw new Error('Template:Armor Ratings: no health or chest factor');
  const missing = new Set();
  const byEnemy = {};
  for (const enemy of enemies) {
    const page = source.pages[pageTitle(enemy)];
    if (!page) continue;
    byEnemy[enemy.id] = {
      page: page.title, revision: page.revision,
      attacks: page.boxes.map(box => {
        const attack = enemyAttack(box, ratings);
        if (!korean[attack.en]) missing.add(attack.en);
        return { name: korean[attack.en] ?? attack.en, ...attack };
      }),
    };
  }
  if (missing.size) throw new Error(`Add Korean names to db/source/enemy_weapon_korean.json:\n  ${[...missing].join('\n  ')}`);
  const unused = Object.keys(korean).filter(en => !Object.values(byEnemy).some(item => item.attacks.some(attack => attack.en === en)));
  if (unused.length) throw new Error(`db/source/enemy_weapon_korean.json has names no enemy uses: ${unused.join(', ')}`);
  return {
    byEnemy,
    helldiver: { health: ratings.health, chest: ratings.chest, head: ratings.head, arm: ratings.arm, leg: ratings.leg, fortified: ratings.fortified, vitality: ratings.vitality, factors: ratings.factors, source: { page: 'https://helldivers.wiki.gg/wiki/Template:Armor_Ratings', revision: source.armorRatings.revision } },
    checkedAt: source.retrievedAt,
  };
}

if (import.meta.url === `file:///${process.argv[1].replaceAll('\\', '/').replace(/^\//, '')}`) {
  const data = await buildEnemyWeapons();
  await writeFile(new URL('../dist/data/enemy-weapons.js', import.meta.url), `// Generated by scripts/build-enemy-weapons.mjs from the Helldivers Wiki enemy pages ("Weapons Loadout")
// and Template:Armor Ratings (CC BY-NC-SA 4.0). Attack names are the site's translation. Do not edit.
// hits: torso hits a Helldiver survives before dying, per armor rating (rough: no AP, falloff or explosions).
export const enemyWeaponsCheckedAt = ${JSON.stringify(data.checkedAt)};
export const helldiverArmor = ${JSON.stringify(data.helldiver)};
export const enemyWeapons = ${JSON.stringify(data.byEnemy, null, 1)};
`);
  const attacks = Object.values(data.byEnemy).flatMap(item => item.attacks);
  console.log(`${Object.keys(data.byEnemy).length} enemies, ${attacks.length} attacks (${attacks.filter(a => a.hits).length} with a hit count, ${attacks.filter(a => a.damage == null && a.explosion == null).length} without a plain number)`);
}
